calc:
/* Calculateur d'adéquation des fonds propres (Bâle III) */
(function () {
  var svg = document.getElementById("cap-chart");
  if (!svg) return;
  var LEV_EXP = 250; // exposition de levier (Md€), fixe
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function draw(){
    var cet1=v("cap-cet1"), at1=v("cap-at1"), t2=v("cap-t2"), rwa=v("cap-rwa"), ccb=v("cap-ccb");
    setT("cap-cet1-o",cet1); setT("cap-at1-o",at1); setT("cap-t2-o",t2); setT("cap-rwa-o",rwa); setT("cap-ccb-o",ccb+"%");
    var cet1r=cet1/rwa*100, t1r=(cet1+at1)/rwa*100, totr=(cet1+at1+t2)/rwa*100, levr=(cet1+at1)/LEV_EXP*100;
    var reqCet1=4.5+2.5+ccb, reqT1=6+2.5+ccb, reqTot=8+2.5+ccb, reqLev=3;
    setT("cap-cet1r",cet1r.toFixed(1)+"%"); setT("cap-t1r",t1r.toFixed(1)+"%"); setT("cap-totr",totr.toFixed(1)+"%"); setT("cap-levr",levr.toFixed(1)+"%");
    var pass = cet1r>=reqCet1 && t1r>=reqT1 && totr>=reqTot && levr>=reqLev;
    var vEl=document.getElementById("cap-verdict");
    if (vEl){
      vEl.textContent = pass ? (al()==="en"?"✓ Compliant":(al()==="nl"?"✓ Conform":"✓ Conforme"))
                             : (al()==="en"?"✗ Below requirement":(al()==="nl"?"✗ Onder de vereiste":"✗ Sous le seuil"));
      vEl.style.background = pass ? "rgba(47,143,106,0.18)" : "rgba(178,58,72,0.18)";
      vEl.style.color = pass ? "#2f8f6a" : "var(--crimson)";
    }

    var labs = al()==="en" ? ["CET1","Tier 1","Total","Leverage"]
             : al()==="nl" ? ["CET1","Tier 1","Totaal","Hefboom"]
             : ["CET1","Tier 1","Total","Levier"];
    var vals=[cet1r,t1r,totr,levr], reqs=[reqCet1,reqT1,reqTot,reqLev];

    var W=520,H=260,L=30,R=16,T=16,B=34, pw=W-L-R, ph=H-T-B;
    var ymax=0; for (var i=0;i<vals.length;i++){ ymax=Math.max(ymax,vals[i],reqs[i]); } ymax*=1.18;
    function py(val){ return T + (1-val/ymax)*ph; }
    var n=vals.length, slot=pw/n, bw=slot*0.46;

    var g="";
    // grille horizontale légère
    for (var gy=0; gy<=ymax; gy+=5){ var yy=py(gy); g+='<line x1="'+L+'" y1="'+yy.toFixed(1)+'" x2="'+(L+pw)+'" y2="'+yy.toFixed(1)+'" stroke="var(--border)" stroke-width="0.7"/>'; g+='<text class="tick" x="'+(L-4)+'" y="'+(yy+3).toFixed(1)+'" text-anchor="end">'+gy+'%</text>'; }
    for (var b2=0;b2<n;b2++){
      var cx=L+slot*b2+slot/2, val=vals[b2], req=reqs[b2];
      var ok=val>=req;
      var yTop=py(val), y0=py(0);
      g+='<rect x="'+(cx-bw/2).toFixed(1)+'" y="'+yTop.toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+(y0-yTop).toFixed(1)+'" rx="2" fill="'+(ok?"var(--teal)":"var(--crimson)")+'" opacity="0.75"/>';
      // valeur
      g+='<text class="tick" x="'+cx.toFixed(1)+'" y="'+(yTop-5).toFixed(1)+'" text-anchor="middle" fill="var(--ink-soft)">'+val.toFixed(1)+'%</text>';
      // ligne d'exigence
      var ry=py(req);
      g+='<line x1="'+(cx-bw/2-4).toFixed(1)+'" y1="'+ry.toFixed(1)+'" x2="'+(cx+bw/2+4).toFixed(1)+'" y2="'+ry.toFixed(1)+'" stroke="var(--gold)" stroke-width="2" stroke-dasharray="4 2"/>';
      // label
      g+='<text class="lab" x="'+cx.toFixed(1)+'" y="'+(H-8)+'" text-anchor="middle">'+labs[b2]+'</text>';
    }
    // ligne de base
    g+='<line class="axis" x1="'+L+'" y1="'+py(0).toFixed(1)+'" x2="'+(L+pw)+'" y2="'+py(0).toFixed(1)+'"/>';
    // légende exigence
    g+='<text class="tick" x="'+(L+pw)+'" y="'+(T+8)+'" text-anchor="end" fill="var(--gold)">'+ (al()==="en"?"— required":(al()==="nl"?"— vereist":"— exigence")) +'</text>';
    svg.innerHTML=g;
  }

  ["cap-cet1","cap-at1","cap-t2","cap-rwa","cap-ccb"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
